<?php
namespace App\Http\Controllers\Front;use App\Http\Controllers\Controller;use App\Models\Address;use Illuminate\Http\Request;
class AddressController extends Controller{private function data(Request $r){return $r->validate(['label'=>'required|string|max:30','recipient_name'=>'required|string|max:100','phone'=>'required|string|max:30','address'=>'required|string|max:1000','city'=>'required|string|max:100','province'=>'required|string|max:100','postal_code'=>'required|string|max:10','is_primary'=>'nullable|boolean']);}public function store(Request $r){$data=$this->data($r);if($r->boolean('is_primary')||!$r->user()->addresses()->exists())$r->user()->addresses()->update(['is_primary'=>false]);$r->user()->addresses()->create($data+['is_primary'=>$r->boolean('is_primary')||!$r->user()->addresses()->exists()]);return back()->with('success','Alamat ditambahkan.');}public function update(Request $r,Address $address){abort_unless($address->user_id===$r->user()->id,403);$data=$this->data($r);if($r->boolean('is_primary'))$r->user()->addresses()->whereKeyNot($address->id)->update(['is_primary'=>false]);$address->update($data+['is_primary'=>$r->boolean('is_primary')]);return back()->with('success','Alamat diperbarui.');}public function destroy(Request $r,Address $address){abort_unless($address->user_id===$r->user()->id,403);$address->delete();return back()->with('success','Alamat dihapus.');}}
